use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let mut parts: Vec<string> = text.split("\n").collect()
    let n: int = parts.len() as int
    if n > 0 && parts[n - 1] == "" {
        parts.pop()
    }
    let mut c = counter
    for p in parts {
        c += 1
        println("${c:>6}\t${p}")
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in env::args() {
        files.push(a)
    }
    let mut names: Vec<string> = []
    let mut first = true
    for a in files {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            names.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if names.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for name in names {
            match fs::read_to_string(name) {
                Ok(t) => {
                    counter = emit(t, number, counter)
                }
                Err(_) => {
                    println("cat: ${name}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}
